    SellerRegistration = apps.get_model("core", "SellerRegistration")
    ReceiptItem = apps.get_model("core", "ReceiptItem")
    UserConsent = apps.get_model("core", "UserConsent")
    database = schema_editor.connection.alias

    global_settings, _ = GlobalSettings.objects.using(database).get_or_create(pk=1)
    prices = []
    for bazaar in Bazaar.objects.using(database).all():
        for price in bazaar.common_prices or []:
            if price not in prices:
                prices.append(price)
    global_settings.common_prices = prices
    latest_bazaar = (
        Bazaar.objects.using(database)
        .exclude(consent_text="")
        .order_by("-starts_at")
        .first()
    )
    if latest_bazaar:
        global_settings.consent_text = latest_bazaar.consent_text
        global_settings.consent_version = latest_bazaar.consent_version
    global_settings.save(using=database)

    for registration in SellerRegistration.objects.using(database).exclude(consented_at=None):
        UserConsent.objects.using(database).get_or_create(
            user_id=registration.seller_id,
            version=registration.consent_version or "legacy",
            text=registration.consent_text,
            accepted_at=registration.consented_at,
        )

    legacy_receipts = (
        ReceiptItem.objects.using(database)
        .filter(registration=None, receipt__registration__isnull=False)
        .values_list("pk", "receipt__registration_id")
    )
    for item_id, registration_id in legacy_receipts.iterator():
        ReceiptItem.objects.using(database).filter(pk=item_id).update(
            registration_id=registration_id
        )


